(()=>{const page=location.pathname.replace(/^\/+|\/+$/g,'')||'home';if(page==='reseller'){document.head.insertAdjacentHTML('beforeend','<style>.reseller-row-plans .reseller-named-plan.no-price{grid-template-columns:minmax(250px,1fr) minmax(350px,1.45fr) auto}@media(max-width:950px){.reseller-row-plans .reseller-named-plan.no-price{grid-template-columns:minmax(220px,1fr) 1fr}.reseller-row-plans .reseller-named-plan.no-price .btn{grid-column:1/-1}}@media(max-width:600px){.reseller-row-plans .reseller-named-plan.no-price{grid-template-columns:1fr}.reseller-row-plans .reseller-named-plan.no-price .btn{grid-column:auto}}</style>');const plans=[['Tivione Starter Reseller Plan','10 Credits','A confident starting point for your first customers.'],['Tivione Growth Reseller Plan','20 Credits','More capacity for a growing customer base.'],['Tivione Pro Reseller Plan','50 Credits','Practical scale for established reseller teams.'],['Tivione Business Reseller Plan','100 Credits','A high-volume package for active operations.'],['Tivione Enterprise Reseller Plan','Grow Package','A tailored credit solution for ambitious growth.']];document.querySelectorAll('.reseller-row-plans .plan').forEach((plan,index)=>{const details=plans[index],title=plan.querySelector('h3');if(!details||!title||plan.querySelector('.reseller-name-block'))return;const block=document.createElement('div');block.className='reseller-name-block';block.innerHTML='<span class="reseller-plan-kicker">TIVIONE RESELLER</span><h3>'+details[0]+'</h3><p class="reseller-credit">'+details[1]+'</p><p class="reseller-plan-description">'+details[2]+'</p>';title.replaceWith(block);const price=plan.querySelector('.price');if(index>0&&price){price.remove();plan.classList.add('no-price');}plan.classList.add('reseller-named-plan');});}if(['home','pricing'].includes(page)){document.querySelectorAll('.subscription-row-plans .plan').forEach(plan=>{if(plan.querySelector('.subscription-overview'))return;const media=plan.querySelector('.plan-media'),title=plan.querySelector('h3'),label=plan.querySelector('.plan-title'),description=plan.querySelector('.plan-description'),price=plan.querySelector('.price'),features=plan.querySelector('.ticks'),button=plan.querySelector('.btn');if(!media||!title||!price||!features||!button)return;const overview=document.createElement('div');overview.className='subscription-overview';overview.append(title);if(label)overview.append(label);if(description)overview.append(description);plan.replaceChildren(media,overview,price,features,button);});}})();
